   CachedOwnerGeometry<DT_PERSON_BOXES,DT_OUTPUT,THRESHOLD_KIND,71,true,false,true,0,false,TILE_CLASS+413> op;
   op.Init(person_boxes,anchor_points,threshold,violation_score,tiling,d,cachedOwner);op.Process();
